function debounceRender(render, wait = 120) {
  let timeout;
  return function(...args) {
    clearTimeout(timeout);
    timeout = setTimeout(() => render.apply(this, args), wait);
  };
}

class NotesWidget {
  constructor() {
    this.notes = new Map();
    this.pendingQueue = [];
    this.sequenceId = 0;
    this.render = debounceRender(this.render.bind(this));
  }

  async init() {
    await this.loadNotes();
    this.connectWebSocket();
    this.registerServiceWorker();
    this.setupOfflineQueue();
  }

  async loadNotes() {
    const res = await fetch('/notes');
    const notes = await res.json();
    notes.forEach(note => this.notes.set(note.id, note));
    this.render();
  }

  connectWebSocket() {
    this.ws = new WebSocket('wss://api.example.com/notes');
    this.ws.onmessage = (event) => {
      const { data } = JSON.parse(event.data);
      if (data.sequenceId >= this.sequenceId) {
        this.sequenceId = data.sequenceId;
        if (!this.notes.has(data.noteId)) {
          this.notes.set(data.noteId, data);
          this.render();
        }
      }
    };
  }

  async addNote(content) {
    const note = { id: crypto.randomUUID(), content, timestamp: Date.now() };
    if (navigator.onLine) {
      await fetch('/notes', {
        method: 'POST',
        body: JSON.stringify(note),
        headers: { 'Content-Type': 'application/json' }
      });
    } else {
      await this.queueNote(note);
    }
  }

  async queueNote(note) {
    const db = await indexedDB.open('notes-queue', 1);
    const tx = db.transaction('pending', 'readwrite');
    tx.objectStore('pending').add({ ...note, retryCount: 0 });
  }

  async syncQueue() {
    const db = await indexedDB.open('notes-queue', 1);
    const tx = db.transaction('pending', 'readwrite');
    const store = tx.objectStore('pending');
    const request = store.getAll();

    request.onsuccess = async () => {
      for (const note of request.result) {
        try {
          await fetch('/notes', {
            method: 'POST',
            body: JSON.stringify(note),
            headers: { 'Content-Type': 'application/json' }
          });
          store.delete(note.id);
        } catch (e) {
          await this.exponentialBackoff(note, note.retryCount++);
        }
      }
    };
  }

  async exponentialBackoff(note, attempt) {
    const delay = Math.min(1000 * Math.pow(2, attempt), 30000);
    setTimeout(() => this.queueNote(note), delay);
  }

  render() {
    // Diff-based DOM update logic here
  }
}
```

## Why This Is Asked
This question tests advanced JavaScript patterns including closures, per-key caching, in-flight deduplication, concurrency control, TTL semantics, and dynamic import boundaries.

## Key Concepts
- **Closures**: Hide internal state from outside access
- **Per-key caching with TTL**: Store module exports with expiration timestamps
- **In-flight deduplication**: Return the same Promise for concurrent requests to the same module
- **Semaphore-like concurrency cap**: Limit simultaneous imports using a counter
- **Background refresh**: Refresh expired modules without blocking subsequent requests

## Code Example
```javascript
function createModuleCache(moduleMap, { ttlMs = 120000, maxInFlight = 3 } = {}) {
  const inFlight = new Map(); // moduleName -> Promise
  const cache = new Map(); // moduleName -> { value, expiry }
  let currentInFlight = 0;

  const acquire = () => new Promise(resolve => {
    const tryAcquire = () => {
      if (currentInFlight < maxInFlight) {
        currentInFlight++;
        resolve();
      } else {
        setTimeout(tryAcquire, 10);
      }
    };
    tryAcquire();
  });

  const release = () => { currentInFlight--; };

  async function load(moduleName) {
    const cached = cache.get(moduleName);
    const isExpired = !cached || Date.now() > cached.expiry;

    if (cached && !isExpired) {
      if (isExpired) {
        load(moduleName).catch(() => {}); // background refresh
      }
      return cached.value;
    }

    if (inFlight.has(moduleName)) {
      return inFlight.get(moduleName);
    }

    const promise = (async () => {
      await acquire();
      try {
        const module = await dynamicImport(moduleMap[moduleName]);
        cache.set(moduleName, {
          value: module,
          expiry: Date.now() + ttlMs
        });
        return module;
      } finally {
        release();
        inFlight.delete(moduleName);
      }
    })();

    inFlight.set(moduleName, promise);
    return promise;
  }

  function invalidate(moduleName) {
    cache.delete(moduleName);
  }

  return { load, invalidate };
}
```

